// ─── Shape Utilities ─────────────────────────────────────────────────────────

export function normalize(cells: Position[]): Position[] {
  const minRow = Math.min(...cells.map(c => c.row));
  const minCol = Math.min(...cells.map(c => c.col));
  return cells.map(c => ({ row: c.row - minRow, col: c.col - minCol }));
}

export function rotate90(cells: Position[]): Position[] {
  // (row, col) → (col, -row) then normalize
  const rotated = cells.map(c => ({ row: c.col, col: -c.row }));
  return normalize(rotated);
}

export function flipHorizontal(cells: Position[]): Position[] {
  const rotated = cells.map(c => ({ row: c.row, col: -c.col }));
  return normalize(rotated);
}

export function getAllOrientations(cells: Position[]): Position[][] {
  const orientations: Position[][] = [];
  let current = normalize(cells);

  for (let i = 0; i < 4; i++) {
    orientations.push(current);
    orientations.push(flipHorizontal(current));
    current = rotate90(current);
  }

  // Deduplicate
  const unique: Position[][] = [];
  const seen = new Set<string>();
  for (const orient of orientations) {
    const key = orient.map(c => `${c.row},${c.col}`).sort().join('|');
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(orient);
    }
  }

  return unique;
}

export function getShapesBySize(size: number): PolyominoShape[] {
  const prefix = size.toString().padStart(2, '0');
  return Object.entries(SHAPES)
    .filter(([id]) => id.startsWith(prefix))
    .map(([id, cells]) => ({ id, cells, size }));
}

export function getShape(id: string): PolyominoShape | null {
  const cells = SHAPES[id];
  if (!cells) return null;
  const size = cells.length;
  return { id, cells, size };
}

export function getAllShapes(): PolyominoShape[] {
  return Object.entries(SHAPES).map(([id, cells]) => ({
    id,
    cells,
    size: cells.length,
  }));
}

